describe('Page Number Jump Navigation', () => {
  beforeEach(() => {
    cy.visit('/pagination');
  });

  it('should jump to a specific page when entering page number in input', () => {
    // Verify initial page is displayed
    cy.get('[data-testid="page-indicator"]').should('contain', 'Page 1');
    cy.get('[data-testid="page-number-input"]').should('be.visible');

    // Enter page number in input field
    cy.get('[data-testid="page-number-input"]').type('5');

    // Click jump button
    cy.get('[data-testid="jump-button"]').click();

    // Verify page has updated
    cy.get('[data-testid="page-indicator"]').should('contain', 'Page 5');
    cy.get('[data-testid="items-list"]').should('be.visible');
    cy.get('[data-testid="items-list"]').should('have.length.greaterThan', 0);
  });

  it('should handle invalid page number input and display error', () => {
    // Verify initial page is displayed
    cy.get('[data-testid="page-indicator"]').should('contain', 'Page 1');
    cy.get('[data-testid="page-number-input"]').should('be.visible');

    // Enter invalid page number
    cy.get('[data-testid="page-number-input"]').type('abc');

    // Click jump button
    cy.get('[data-testid="jump-button"]').click();

    // Verify error message is displayed
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Please enter a valid page number');

    // Verify page has not changed
    cy.get('[data-testid="page-indicator"]').should('contain', 'Page 1');
  });
});
